@Subgroup.card_mul_index : ∀ {G : Type u_1} [inst : Group G] (H : Subgroup G), Nat.card ↥H * H.index = Nat.card G
MulAction.index_stabilizer : ∀ (G : Type u_1) {X : Type u_2} [inst : Group G] [inst_1 : MulAction G X] (x : X),
  (MulAction.stabilizer G x).index = (MulAction.orbit G x).ncard
MulAction.exists_smul_eq : ∀ (M : Type u_1) {α : Type u_2} [inst : SMul M α] [MulAction.IsPretransitive M α] (x y : α),
  ∃ m, m • x = y
@Gal.smul_def : ∀ {F : Type u_1} [inst : Field F] (p : F[X]) (E : Type u_2) [inst_1 : Field E] [inst_2 : Algebra F E]
  [inst_3 : Fact (map (algebraMap F E) p).Splits] (ϕ : p.Gal) (x : ↑(p.rootSet E)),
  ϕ • x = (Gal.rootsEquivRoots p E) (ϕ • (Gal.rootsEquivRoots p E).symm x)
@Equiv.subtypeEquiv : {α : Sort u_1} →
  {β : Sort u_2} →
    {p : α → Prop} → {q : β → Prop} → (e : α ≃ β) → (∀ (a : α), p a ↔ q (e a)) → { a // p a } ≃ { b // q b }

